:root {
  --bg: #0b0d10;
  --bg-2: #111418;
  --surface: #161a20;
  --surface-2: #1d2229;
  --line: #2a313b;
  --line-strong: #3a424f;
  --text: #ecedef;
  --text-muted: #aab1bd;
  --text-dim: #7e8694;
  --accent: #e8c79a;          /* warm sand */
  --accent-strong: #f3d4ac;
  --accent-ink: #1a1308;
  --hot: #ff8a6b;
  --focus: #9ad0ff;
  --shadow: 0 12px 40px rgba(0,0,0,0.45);
  --radius: 14px;
  --radius-sm: 10px;
  --maxw: 1200px;
}

* { box-sizing: border-box; }

html { color-scheme: dark; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: "Inter", "Helvetica Neue", system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img, svg { display: block; max-width: 100%; }

a { color: inherit; text-decoration: none; }
a:hover { text-decoration: underline; text-underline-offset: 3px; }

p { margin: 0 0 0.75em; }

h1, h2, h3, h4 { font-family: "Fraunces", "Cormorant Garamond", Georgia, "Times New Roman", serif; font-weight: 500; letter-spacing: -0.01em; line-height: 1.15; margin: 0 0 0.4em; }

button { font: inherit; color: inherit; }

/* Focus */
:where(a, button, input, [tabindex]):focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 3px;
  border-radius: 6px;
}

.sr-only {
  position: absolute !important; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute; left: 12px; top: -40px;
  background: var(--accent); color: var(--accent-ink);
  padding: 10px 14px; border-radius: 8px; font-weight: 600; z-index: 100;
  transition: top .15s ease;
}
.skip-link:focus { top: 12px; outline: 2px solid var(--focus); outline-offset: 3px; text-decoration: none; }

.container { width: min(100% - 40px, var(--maxw)); margin-inline: auto; }

/* Header ----------------------------------------------------- */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(11, 13, 16, 0.85);
  backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: flex; align-items: center; gap: 24px;
  min-height: 68px;
}
.brand {
  display: inline-flex; align-items: baseline; gap: 8px;
  font-family: "Fraunces", Georgia, serif;
}
.brand-mark { color: var(--accent); font-size: 1.3em; }
.brand-name { font-weight: 600; letter-spacing: 0.18em; font-size: 0.95rem; }

.primary-nav { margin-inline-start: 16px; }
.primary-nav ul { display: flex; gap: 4px; list-style: none; padding: 0; margin: 0; flex-wrap: wrap; }
.primary-nav a {
  display: inline-block; padding: 10px 14px; border-radius: 8px;
  color: var(--text-muted); font-size: 0.93rem; font-weight: 500;
}
.primary-nav a:hover { color: var(--text); background: var(--surface); text-decoration: none; }

.header-actions { margin-inline-start: auto; display: inline-flex; align-items: center; gap: 4px; }
.icon-btn {
  position: relative;
  display: inline-flex; align-items: center; justify-content: center;
  width: 40px; height: 40px; border-radius: 10px;
  background: transparent; border: 1px solid transparent; color: var(--text-muted);
  cursor: pointer;
}
.icon-btn:hover { color: var(--text); background: var(--surface); border-color: var(--line); }
.cart-count {
  position: absolute; top: 4px; right: 4px;
  background: var(--accent); color: var(--accent-ink);
  font-size: 10px; font-weight: 700; min-width: 16px; height: 16px;
  border-radius: 8px; display: inline-flex; align-items: center; justify-content: center;
  padding: 0 4px;
}

.search-panel { border-top: 1px solid var(--line); background: var(--bg-2); padding: 14px 0; }
.search-form { display: flex; gap: 10px; }
.search-form input {
  flex: 1; min-width: 0;
  background: var(--surface); border: 1px solid var(--line); color: var(--text);
  padding: 12px 14px; border-radius: 10px; font-size: 0.95rem;
}
.search-form input::placeholder { color: var(--text-dim); }

/* Buttons ---------------------------------------------------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 12px 20px; border-radius: 999px;
  font-weight: 600; font-size: 0.95rem; letter-spacing: 0.01em;
  border: 1px solid transparent; cursor: pointer; text-decoration: none;
  transition: transform .08s ease, background .15s ease, color .15s ease, border-color .15s ease;
}
.btn:hover { text-decoration: none; }
.btn:active { transform: translateY(1px); }
.btn-primary { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
.btn-primary:hover { background: var(--accent-strong); border-color: var(--accent-strong); }
.btn-ghost { background: transparent; color: var(--text); border-color: var(--line-strong); }
.btn-ghost:hover { background: var(--surface); border-color: var(--text-muted); }

.eyebrow {
  text-transform: uppercase; letter-spacing: 0.2em; font-size: 0.72rem;
  color: var(--accent); font-weight: 600; margin: 0 0 0.6em;
}

.section-title { font-size: clamp(1.6rem, 2.4vw + 0.6rem, 2.4rem); margin: 0; }

.section-header {
  display: flex; align-items: end; justify-content: space-between; gap: 16px;
  margin-bottom: 28px; flex-wrap: wrap;
}
.link-arrow {
  color: var(--text); font-weight: 600; font-size: 0.92rem;
  border-bottom: 1px solid var(--line-strong); padding-bottom: 2px;
}
.link-arrow:hover { color: var(--accent); border-bottom-color: var(--accent); text-decoration: none; }

/* Hero ------------------------------------------------------- */
.hero { padding: 56px 0 64px; border-bottom: 1px solid var(--line); position: relative; overflow: hidden; }
.hero::before {
  content: ""; position: absolute; inset: -20% -10% auto -10%; height: 60%;
  background: radial-gradient(60% 60% at 30% 20%, rgba(232,199,154,0.12), transparent 70%),
              radial-gradient(40% 50% at 80% 30%, rgba(154,208,255,0.08), transparent 70%);
  pointer-events: none;
}
.hero-inner {
  display: grid; grid-template-columns: 1.1fr 1fr; gap: 56px; align-items: center;
  position: relative;
}
.hero h1 {
  font-size: clamp(2.4rem, 4.6vw + 0.4rem, 4.4rem);
  letter-spacing: -0.02em;
  margin-bottom: 0.4em;
}
.lede { color: var(--text-muted); font-size: 1.08rem; max-width: 52ch; }
.hero-cta { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 24px; }

.hero-meta {
  list-style: none; padding: 0; margin: 36px 0 0;
  display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 12px;
  border-top: 1px solid var(--line); padding-top: 20px;
}
.hero-meta li { color: var(--text-muted); font-size: 0.88rem; }
.hero-meta strong { display: block; color: var(--text); font-weight: 600; }

.hero-art {
  position: relative; aspect-ratio: 5/4; min-height: 360px;
}
.hero-card {
  position: absolute; border-radius: 18px; box-shadow: var(--shadow);
  border: 1px solid var(--line);
}
.hero-card-1 {
  inset: 6% 18% 18% 0;
  background:
    radial-gradient(120% 80% at 30% 30%, #3a3128 0%, #1a1612 60%, #0f0d0b 100%);
}
.hero-card-1::after {
  content: ""; position: absolute; inset: 18% 22% 22% 18%;
  background: radial-gradient(60% 60% at 50% 50%, #6b5640 0%, #2a2117 70%);
  border-radius: 50%; box-shadow: inset 0 0 60px rgba(0,0,0,0.6);
}
.hero-card-2 {
  inset: 0 0 38% 38%;
  background: linear-gradient(160deg, #2a3540 0%, #11161c 100%);
}
.hero-card-2::after {
  content: ""; position: absolute; inset: 14%;
  background: linear-gradient(180deg, transparent 0%, transparent 60%, #4a5563 60%, #4a5563 62%, transparent 62%);
  border-radius: 8px;
  background-image:
    linear-gradient(180deg, #d2b896 0%, #a5876a 100%);
  border-radius: 6px;
}
.hero-card-3 {
  inset: 42% 4% 4% 32%;
  background: linear-gradient(150deg, #c9a780 0%, #6e5536 100%);
}
.hero-card-3::after {
  content: ""; position: absolute; inset: 22% 28%;
  background: repeating-linear-gradient(45deg, rgba(0,0,0,0.18) 0 8px, transparent 8px 16px);
  border-radius: 6px;
}
.hero-glow {
  position: absolute; inset: -10%;
  background: radial-gradient(40% 40% at 70% 30%, rgba(232,199,154,0.18), transparent 70%);
  pointer-events: none; z-index: -1;
}

/* Categories ------------------------------------------------- */
.categories { padding: 48px 0; border-bottom: 1px solid var(--line); }
.cat-grid {
  list-style: none; padding: 0; margin: 24px 0 0;
  display: grid; grid-template-columns: repeat(6, minmax(0,1fr)); gap: 12px;
}
.cat-grid a {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 10px; padding: 22px 12px;
  background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--radius); color: var(--text);
  font-weight: 500; font-size: 0.92rem;
  transition: background .15s, border-color .15s, transform .15s;
}
.cat-grid a:hover { background: var(--surface-2); border-color: var(--line-strong); transform: translateY(-2px); text-decoration: none; }
.cat-emoji { font-size: 1.6rem; }

/* Featured products ----------------------------------------- */
.featured { padding: 64px 0; border-bottom: 1px solid var(--line); }

.filter-bar { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 24px; }
.chip {
  padding: 8px 14px; border-radius: 999px;
  background: var(--surface); border: 1px solid var(--line); color: var(--text-muted);
  font-size: 0.86rem; cursor: pointer;
}
.chip:hover { color: var(--text); border-color: var(--line-strong); }
.chip.is-active { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); font-weight: 600; }

.product-grid {
  list-style: none; padding: 0; margin: 0;
  display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: 22px;
}
.product {
  background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--radius); overflow: hidden;
  display: flex; flex-direction: column;
  transition: transform .2s ease, border-color .2s ease;
}
.product:hover { transform: translateY(-3px); border-color: var(--line-strong); }
.product-art {
  aspect-ratio: 4/5; position: relative; overflow: hidden;
  background: var(--surface-2);
}
.product-art::after {
  content: ""; position: absolute; inset: 18%;
  border-radius: 12px;
}
.product-art .badge {
  position: absolute; top: 12px; left: 12px; z-index: 2;
}
.product-art .fav {
  position: absolute; top: 10px; right: 10px; z-index: 2;
  width: 36px; height: 36px; border-radius: 50%;
  background: rgba(11,13,16,0.6); border: 1px solid var(--line);
  color: var(--text); display: inline-flex; align-items: center; justify-content: center;
  cursor: pointer;
}
.product-art .fav:hover { background: var(--surface-2); }
.product-art .fav[aria-pressed="true"] { color: var(--hot); border-color: var(--hot); }

.product-art.art-1 { background: linear-gradient(160deg, #2b231b 0%, #15110d 100%); }
.product-art.art-1::after { background: radial-gradient(60% 80% at 50% 40%, #c9a374 0%, #6b5234 60%, transparent 70%); }
.product-art.art-2 { background: linear-gradient(160deg, #1d2530 0%, #0d1218 100%); }
.product-art.art-2::after { background: linear-gradient(180deg, #d8d3cb 0%, #8d8377 100%); }
.product-art.art-3 { background: linear-gradient(160deg, #2c2a26 0%, #16140f 100%); }
.product-art.art-3::after { background: radial-gradient(50% 50% at 50% 55%, #4a3a28 0%, #2a1f12 60%, transparent 70%); border-radius: 50%; inset: 22%; }
.product-art.art-4 { background: linear-gradient(160deg, #1f2622 0%, #0e1311 100%); }
.product-art.art-4::after { background: linear-gradient(180deg, #2f3b34 0%, #6b8076 100%); }
.product-art.art-5 { background: linear-gradient(160deg, #2a2026 0%, #140e12 100%); }
.product-art.art-5::after { background: radial-gradient(60% 60% at 50% 50%, #b78a8a 0%, #5a3a3a 70%); }
.product-art.art-6 { background: linear-gradient(160deg, #25241e 0%, #11100b 100%); }
.product-art.art-6::after { background: linear-gradient(180deg, #cdbf9a 0%, #7a6c4c 100%); }
.product-art.art-7 { background: linear-gradient(160deg, #1c2026 0%, #0c1015 100%); }
.product-art.art-7::after { background: radial-gradient(60% 50% at 50% 60%, #6c83a0 0%, #2c3a4d 70%, transparent 80%); }
.product-art.art-8 { background: linear-gradient(160deg, #271e1a 0%, #14100d 100%); }
.product-art.art-8::after { background: radial-gradient(40% 60% at 50% 50%, #e0c89a 0%, #80633c 70%, transparent 80%); border-radius: 50%; inset: 28% 36%; }

.product-body { padding: 16px 18px 20px; display: flex; flex-direction: column; gap: 6px; flex: 1; }
.product-meta { color: var(--text-dim); font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.12em; }
.product-name {
  font-family: inherit; font-weight: 500; font-size: 1rem;
  color: var(--text); margin: 2px 0 6px;
}
.product-name a { color: inherit; }
.product-name a:hover { color: var(--accent); text-decoration: none; }
.product-rating { color: var(--text-muted); font-size: 0.82rem; display: inline-flex; align-items: center; gap: 6px; }
.product-rating .stars { color: var(--accent); letter-spacing: 1px; }
.product-foot { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-top: 10px; }
.price { margin: 0; font-weight: 600; color: var(--text); display: inline-flex; align-items: baseline; gap: 8px; }
.price-now { font-size: 1.05rem; }
.price-was { color: var(--text-dim); text-decoration: line-through; font-weight: 400; font-size: 0.9rem; }

.add-btn {
  background: transparent; border: 1px solid var(--line-strong); color: var(--text);
  padding: 8px 12px; border-radius: 999px; font-size: 0.82rem; font-weight: 600; cursor: pointer;
}
.add-btn:hover { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }

.badge {
  display: inline-block; padding: 4px 10px; border-radius: 999px;
  background: var(--surface-2); color: var(--text); border: 1px solid var(--line);
  font-size: 0.72rem; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase;
}
.badge-hot { background: var(--hot); color: #1a0a05; border-color: var(--hot); }
.badge-new { background: #2c3b4f; color: #cfe3ff; border-color: #3a4d66; }

/* Deals ------------------------------------------------------ */
.deals { padding: 64px 0; border-bottom: 1px solid var(--line); }
.countdown { color: var(--text-muted); font-size: 0.9rem; margin: 0; }
.countdown time { color: var(--accent); font-variant-numeric: tabular-nums; font-weight: 600; }

.deals-grid {
  display: grid; grid-template-columns: 2fr 1fr 1fr; gap: 22px;
}
.deal {
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  overflow: hidden; display: flex; flex-direction: column;
}
.deal-feature { grid-row: span 2; flex-direction: column; }
.deal-feature .deal-art { aspect-ratio: 16/10; }
.deal-feature h3 { font-size: clamp(1.4rem, 1.6vw + 0.6rem, 1.9rem); }
.deal-feature p { color: var(--text-muted); }

.deal-art { aspect-ratio: 16/9; position: relative; }
.deal-art-1 {
  background:
    radial-gradient(60% 60% at 30% 50%, #7a3a2c 0%, #2a1410 60%, #120808 100%);
}
.deal-art-1::after {
  content: ""; position: absolute; inset: 18% 22%;
  background: radial-gradient(60% 70% at 50% 50%, #b8472f 0%, #5a1f15 70%);
  border-radius: 50%;
}
.deal-art-2 {
  background: linear-gradient(160deg, #2a2e36 0%, #0f1216 100%);
}
.deal-art-2::after {
  content: ""; position: absolute; inset: 22% 18%;
  background: linear-gradient(180deg, #cbc4b6 0%, #8b8474 100%);
  border-radius: 8px;
}
.deal-art-3 {
  background: linear-gradient(160deg, #2b231a 0%, #14100b 100%);
}
.deal-art-3::after {
  content: ""; position: absolute; inset: 26% 26% 14% 26%;
  background: linear-gradient(180deg, #6b4a2b 0%, #3a2814 100%);
  border-radius: 4px;
}

.deal-body { padding: 20px 22px 24px; display: flex; flex-direction: column; gap: 8px; flex: 1; }
.deal-body h3 { margin: 8px 0 4px; font-size: 1.15rem; }
.deal-body .badge { align-self: flex-start; }
.deal-body .btn { align-self: flex-start; margin-top: 10px; }

/* Editorial -------------------------------------------------- */
.editorial { padding: 64px 0; border-bottom: 1px solid var(--line); }
.editorial-grid {
  display: grid; grid-template-columns: 1.4fr 1fr 1fr; grid-template-rows: auto auto; gap: 22px;
}
.story { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; }
.story-link { display: flex; flex-direction: column; height: 100%; color: inherit; }
.story-link:hover { text-decoration: none; }
.story-link:hover h3 { color: var(--accent); }
.story-art { position: relative; aspect-ratio: 16/10; }
.story-tag {
  position: absolute; top: 12px; left: 12px;
  background: rgba(11,13,16,0.7); border: 1px solid var(--line);
  color: var(--text); font-size: 0.72rem; padding: 4px 10px; border-radius: 999px;
  text-transform: uppercase; letter-spacing: 0.12em; font-weight: 600;
}
.story-art-1 { background: linear-gradient(160deg, #3a2a1c 0%, #150e08 100%); }
.story-art-1::after { content: ""; position: absolute; inset: 30% 20%; background: radial-gradient(60% 60% at 50% 50%, #d27a3e 0%, #5a2a14 70%); border-radius: 50%; }
.story-art-2 { background: linear-gradient(160deg, #2a3138 0%, #10141a 100%); }
.story-art-2::after { content: ""; position: absolute; inset: 25% 30%; background: linear-gradient(180deg, #d8c8a8 0%, #6e6041 100%); border-radius: 6px; }
.story-art-3 { background: linear-gradient(160deg, #1c2025 0%, #0c0f13 100%); }
.story-art-3::after { content: ""; position: absolute; inset: 28% 32%; background: radial-gradient(50% 50% at 50% 50%, #5a3a22 0%, #1f1408 70%); border-radius: 50%; }
.story-art-4 { background: linear-gradient(160deg, #1f2a26 0%, #0d1311 100%); }
.story-art-4::after { content: ""; position: absolute; inset: 35% 25%; background: linear-gradient(180deg, #8aa090 0%, #3d4f44 100%); border-radius: 4px; }

.story-lead { grid-row: span 2; }
.story-lead .story-art { aspect-ratio: 4/3; }
.story-lead h3 { font-size: clamp(1.3rem, 1.4vw + 0.6rem, 1.7rem); }

.story-body { padding: 18px 22px 22px; display: flex; flex-direction: column; gap: 6px; flex: 1; }
.story-body h3 { margin: 4px 0 0; font-size: 1.05rem; transition: color .15s; }
.story .meta { color: var(--text-dim); font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.12em; margin: 0; }

/* Newsletter ------------------------------------------------- */
.newsletter { padding: 72px 0; border-bottom: 1px solid var(--line); background: var(--bg-2); }
.news-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 56px; align-items: center; }
.news-form { display: flex; flex-direction: column; gap: 14px; }
.field { display: flex; flex-direction: column; gap: 6px; }
.field label { font-size: 0.9rem; color: var(--text); font-weight: 500; }
.field .req { color: var(--accent); }
.field input {
  background: var(--surface); border: 1px solid var(--line); color: var(--text);
  padding: 14px 16px; border-radius: 10px; font-size: 1rem;
}
.field input::placeholder { color: var(--text-dim); }
.field input[aria-invalid="true"] { border-color: var(--hot); }
.help { color: var(--text-muted); font-size: 0.82rem; margin: 0; }
.error { color: var(--hot); font-size: 0.85rem; margin: 0; font-weight: 500; }
.form-status { color: var(--accent); font-size: 0.9rem; margin: 0; min-height: 1.2em; }
.news-form .btn { align-self: flex-start; }

/* Footer ----------------------------------------------------- */
.site-footer { padding: 56px 0 28px; background: #08090b; }
.footer-inner {
  display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 32px;
  padding-bottom: 36px; border-bottom: 1px solid var(--line);
}
.footer-brand p { color: var(--text-muted); margin-top: 12px; max-width: 36ch; font-size: 0.9rem; }
.footer-h { font-family: inherit; font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.18em; color: var(--text); margin: 0 0 14px; font-weight: 600; }
.site-footer ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 10px; }
.site-footer a { color: var(--text-muted); font-size: 0.9rem; }
.site-footer a:hover { color: var(--text); }

.footer-bottom {
  display: flex; justify-content: space-between; align-items: center;
  padding-top: 22px; color: var(--text-dim); font-size: 0.85rem; gap: 16px; flex-wrap: wrap;
}
.legal { list-style: none; padding: 0; margin: 0; display: flex; gap: 18px; }

/* Toast ------------------------------------------------------ */
.toast {
  position: fixed; bottom: 22px; left: 50%; transform: translateX(-50%);
  background: var(--surface-2); border: 1px solid var(--line-strong); color: var(--text);
  padding: 12px 18px; border-radius: 999px; box-shadow: var(--shadow);
  z-index: 200; font-size: 0.92rem; font-weight: 500;
  animation: toast-in .2s ease;
}
@keyframes toast-in {
  from { opacity: 0; transform: translate(-50%, 8px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}

/* Reflow / responsive ---------------------------------------- */
@media (max-width: 1024px) {
  .hero-inner { grid-template-columns: 1fr; gap: 28px; }
  .hero-art { min-height: 320px; }
  .product-grid { grid-template-columns: repeat(3, minmax(0,1fr)); }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-feature { grid-column: span 2; grid-row: auto; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .story-lead { grid-column: span 2; grid-row: auto; }
  .news-inner { grid-template-columns: 1fr; gap: 28px; }
  .footer-inner { grid-template-columns: 1fr 1fr; }
  .cat-grid { grid-template-columns: repeat(3, minmax(0,1fr)); }
}

@media (max-width: 640px) {
  .primary-nav { display: none; }
  .product-grid { grid-template-columns: repeat(2, minmax(0,1fr)); gap: 14px; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-feature { grid-column: auto; }
  .editorial-grid { grid-template-columns: 1fr; }
  .story-lead { grid-column: auto; }
  .footer-inner { grid-template-columns: 1fr; gap: 24px; }
  .hero-meta { grid-template-columns: 1fr; }
  .hero { padding: 36px 0 44px; }
  .featured, .deals, .editorial, .categories { padding: 44px 0; }
  .cat-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}

/* Forced colors --------------------------------------------- */
@media (forced-colors: active) {
  .btn, .chip, .icon-btn, .add-btn, .product, .deal, .story, .cat-grid a, .field input, .search-form input {
    border: 1px solid ButtonBorder;
    background: Canvas;
    color: CanvasText;
  }
  .btn-primary { background: ButtonText; color: ButtonFace; }
  :where(a, button, input, [tabindex]):focus-visible { outline: 2px solid Highlight; }
  .cart-count, .badge { background: Canvas; color: CanvasText; border: 1px solid ButtonBorder; }
}

