    { id: 7, name: 'Indigo Wool Cushion', cat: 'living', price: 72, was: null, rating: 4.6, reviews: 58, art: 7, badge: { text: 'New', cls: 'badge-new' } },
    { id: 8, name: 'Amber & Cedar Diffuser', cat: 'scent', price: 42, was: 52, rating: 4.7, reviews: 167, art: 8 }
  ];

  // Render products --------------------------------------------
  const grid = document.getElementById('productGrid');

  function priceMarkup(p) {
    if (p.was) {
      return `<p class="price"><span class="price-now">$${p.price}</span><span class="price-was"><span class="sr-only">Original price </span>$${p.was}</span></p>`;
    }
    return `<p class="price"><span class="price-now">$${p.price}</span></p>`;
  }

  function stars(rating) {
    const full = Math.round(rating);
    return '★'.repeat(full) + '☆'.repeat(5 - full);
  }

  function renderProducts(filter = 'all') {
    const items = products.filter(p => filter === 'all' || p.cat === filter);
    grid.innerHTML = items.map(p => `
      <li class="product" data-cat="${p.cat}">
        <div class="product-art art-${p.art}">
          ${p.badge ? `<span class="badge ${p.badge.cls}">${p.badge.text}</span>` : ''}
          <button type="button" class="fav" aria-pressed="false" aria-label="Save ${p.name} to favorites">
            <svg aria-hidden="true" viewBox="0 0 24 24" width="18" height="18" focusable="false">
              <path d="M12 21s-7-4.5-9.5-9A5.5 5.5 0 0 1 12 6a5.5 5.5 0 0 1 9.5 6C19 16.5 12 21 12 21z" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/>
            </svg>
          </button>
        </div>
        <div class="product-body">
          <p class="product-meta">${p.cat}</p>
          <h3 class="product-name"><a href="#">${p.name}</a></h3>
          <p class="product-rating"><span class="stars" aria-hidden="true">${stars(p.rating)}</span><span class="sr-only">Rated ${p.rating} out of 5.</span> ${p.rating} <span aria-hidden="true">·</span> <span class="sr-only">based on </span>${p.reviews} reviews</p>
          <div class="product-foot">
            ${priceMarkup(p)}
            <button type="button" class="add-btn" data-id="${p.id}" aria-label="Add ${p.name} to cart">Add</button>
          </div>
        </div>
      </li>
    `).join('');
  }

  renderProducts();

  // Filter chips (tablist behavior) -----------------------------
  const chips = document.querySelectorAll('.chip');
  chips.forEach((chip, i) => {
    chip.addEventListener('click', () => activateChip(chip));
    chip.addEventListener('keydown', (e) => {
      const arr = Array.from(chips);
      const idx = arr.indexOf(chip);
      let next = -1;
      if (e.key === 'ArrowRight') next = (idx + 1) % arr.length;
